"""Shared lists."""


class NotFound(Exception):
    pass


class Forbidden(Exception):
    pass


def create_list(store, list_id, owner):
    store[list_id] = {"owner": owner, "shared_with": set(), "items": []}


def share_list(store, list_id, user, with_user):
    record = _get(store, list_id)
    if record["owner"] != user:
        raise Forbidden("only the owner can share a list")
    record["shared_with"].add(with_user)


def add_item(store, list_id, user, item):
    record = _get(store, list_id)
    if user != record["owner"] and user not in record["shared_with"]:
        raise Forbidden("no access to this list")
    record["items"].append(item)


def delete_list(store, list_id, user):
    record = _get(store, list_id)
    if user != record["owner"] and user not in record["shared_with"]:
        raise Forbidden("no access to this list")
    del store[list_id]


def _get(store, list_id):
    if list_id not in store:
        raise NotFound(list_id)
    return store[list_id]

